mapper.select:
SELECT * FROM (
    SELECT rownum rnum, a.* FROM (
        SELECT 
            NOTICE_NO as notice_no,
            TITLE as title,
            WRITER as writer,
            IS_REPLY as is_reply,
            PARENT_NO as parent_no,
            BOARD_TYPE as board_type,
            TO_CHAR(INDATE, 'YYYY-MM-DD HH24:MI:SS') as indate,
            /* 해당 글을 부모로 하는 답변의 개수를 세어옴 */
            (SELECT COUNT(*) FROM BOARD WHERE PARENT_NO = B.NOTICE_NO) as reply_count
        FROM BOARD B
        WHERE BOARD_TYPE = #{boardType}

        ORDER BY 
            CASE WHEN PARENT_NO = 0 THEN NOTICE_NO ELSE PARENT_NO END DESC,
            INDATE ASC
    ) a WHERE rownum <= #{pageEnd}
) WHERE rnum >= #{pageStart}
